	zip.Describe("github.com/hanzoai/cloud/apps/git GET /v1/git/runners", zip.Doc{
		Description: "Returns the runners that can run the caller's work, each with\nwhen it was last heard from, and the health of every pool.\n\nFirst the forge's: the runners registered on git.hanzo.ai, which run every\nrepository whose home is there — the platform starts one for each job the\nforge queues, labelled as the job asked. Then the daemons registered into this\norg's own declared pools. Pools groups the forge's by label set, with the\ncaller's jobs queued on each, so a label set with work waiting and no runner\nonline — a dead pool — is visible.\n\nThe forge's runners serve every tenant and are named for the repository whose\njob they took, so they are listed by name to a SuperAdmin; anyone else sees\nthe pools their own queued jobs wait on — the jobs of repositories the forge\nlets them read — with how many runners carry each and when one was last heard.",
		Fields: map[string]string{
			"poolHealth.busy":       "Busy is how many of those are executing a job now.",
			"poolHealth.labels":     "Labels are the labels in it.",
			"poolHealth.lastOnline": "LastOnline is when any of them was last heard from, in unix seconds; 0 when\nnone ever was, or the forge does not say.",
			"poolHealth.online":     "Online is how many of those the forge heard from lately.",
			"poolHealth.pool":       "Pool is the label set, sorted and joined by \"+\".",
			"poolHealth.queued":     "Queued is how many of the caller's jobs are waiting for a runner with this\nlabel set. Queued with nothing Online is a dead pool.",
			"poolHealth.runners":    "Runners is how many registered forge runners carry every one of them.",
			"runnerList.data":       "Data is the runners that can run the caller's work: the forge's, then the\ndaemons registered into this org's pools, newest first.",
			"runnerList.fault":      "Fault says why the forge's runners are missing from this answer, when the\nforge could not be read; the daemons here are listed either way.",
			"runnerList.pools":      "Pools is each label set a forge runner answers to or a queued job asks for,\nwith how many runners carry it, how many of those are online, and how many\nof the caller's jobs wait on it. A pool with jobs queued and no runner\nonline is a dead pool.",
			"runnerView.busy":       "Busy is whether it is executing a job now. Known for a forge runner only.",
			"runnerView.ephemeral":  "Ephemeral means the daemon takes ONE job and exits, so it is not expected\nback and its absence is not a fault.",
			"runnerView.forge":      "Forge is true for a runner registered on the forge (git.hanzo.ai), which\nruns the repositories whose home is there, and false for a daemon in one of\nthis org's declared pools.",
			"runnerView.labels":     "Labels are what the daemon last said it can do.",
			"runnerView.lastActive": "LastActive is when it was last EXECUTING a job, in unix seconds. It lags\nLastOnline on an idle daemon, which is how the two differ.",
			"runnerView.lastOnline": "LastOnline is when it last called at all, in unix seconds.",
			"runnerView.name":       "Name is what the daemon called itself when it registered.",
			"runnerView.online":     "Online is whether it was heard from lately: within the forge's offline\nwindow for a forge runner, within a minute for a daemon here.",
			"runnerView.pool":       "Pool is the declared capacity it entered; for a runner on the forge, the\nlabel set it answers to, sorted and joined by \"+\".",
			"runnerView.version":    "Version is the runner build the daemon last reported.",
		},
	})
	zip.Describe("github.com/hanzoai/cloud/apps/git GET /v1/git/runs", zip.Doc{
		Description: "Returns this org's runs, newest first.\n\nA repository named owner/name is on the forge, and its runs are the forge's:\nthe newest, or, when a ref is named, every run on the commit it resolves to,\neach with its jobs and steps and the ref's verdict in State.",
		Fields: map[string]string{
			"runJob.endedAt":        "EndedAt is when it finished, RFC 3339; absent until it has.",
			"runJob.id":             "ID addresses the job, as `runs logs --job` takes it.",
			"runJob.labels":         "Labels are what the job's runs-on asked for.",
			"runJob.name":           "Name is the job's name in the workflow document.",
			"runJob.runner":         "Runner is the runner that took the job; empty until one has.",
			"runJob.startedAt":      "StartedAt is when it started, RFC 3339; absent until it has.",
			"runJob.status":         "Status is waiting, running, or how the job ended, as a run's is.",
			"runJob.steps":          "Steps are the job's steps in order: where in it a failure was.",
			"runJob.url":            "URL is the job's page on the forge.",
			"runQuery.limit":        "Limit caps the answer; 0 means the default of 50, and 200 is the ceiling.",
			"runQuery.ref":          "Ref keeps one branch, tag or commit. On the forge it is resolved to its\ncommit and every run on that commit is answered with its jobs, and State\nsays whether the ref is green; here it keeps the runs of that branch.",
			"runQuery.repo":         "Repo restricts the listing to one repository. owner/name, such as\nhanzo-inc/cloud, is a repository on the forge, and its runs are the forge's;\na bare name is one this app holds. Empty lists the whole org's runs here.",
			"runStep.name":          "Name is the step's name in the workflow document.",
			"runStep.number":        "Number is the step's position in its job, from 1.",
			"runStep.status":        "Status is waiting, running, or how the step ended.",
			"workflowRun.actor":     "Actor is who caused it.",
			"workflowRun.attempt":   "Attempt counts the forge's re-runs of this run, from 1.",
			"workflowRun.commit":    "Commit is the commit being run, in full.",
			"workflowRun.createdAt": "CreatedAt is when the run was opened, in unix seconds.",
			"workflowRun.endedAt":   "EndedAt is when it finished, RFC 3339; absent until it has.",
			"workflowRun.event":     "Event is what caused the run, e.g. \"push\".",
			"workflowRun.id":        "ID addresses this run.",
			"workflowRun.jobs":      "Jobs are the run's jobs in the order they were created, with their steps:\nanswered by `runs get`, and by `runs list` when a ref names one commit.",
			"workflowRun.number":    "Number is the run's position in its repository, counting from 1 — the\nhandle a person uses (\"#4\").",
			"workflowRun.ref":       "Ref is the full ref, e.g. \"refs/heads/main\".",
			"workflowRun.repo":      "Repo is the repository the run is for.",
			"workflowRun.startedAt": "StartedAt is when it started executing, RFC 3339; absent until it has.",
			"workflowRun.status":    "Status is waiting, running, success, failure, cancelled or skipped: waiting\nuntil a runner takes it (or, on the forge, while a job it needs is still\ngoing), running while it executes, and then how it ended.",
			"workflowRun.title":     "Title is the run's display title on the forge, usually its commit's subject.",
			"workflowRun.updatedAt": "UpdatedAt is when its status last changed, in unix seconds.",
			"workflowRun.url":       "URL is the run's page on the forge.",
			"workflowRun.workflow":  "Workflow is the path of the document being run, e.g.\n\".hanzo/workflows/ci.yml\".",
			"workflowRuns.commit":   "Commit is the commit a ref named, when the listing asked for one: the runs\nare the ones on it, and a branch that moves does not move them.",
			"workflowRuns.data":     "Data is the runs in scope, newest first.",
			"workflowRuns.state":    "State answers \"is this ref green?\" when the listing named a forge ref:\npassed, failed, running, queued or none. It is read over the latest attempt\nof each workflow on the commit: any failed or cancelled run or job is\nfailed; otherwise any still going is running, any waiting for a runner is\nqueued, and when everything finished as success or skipped it is passed.\nnone means nothing ran.",
		},
		Example: json.RawMessage(`{"repo":"hanzo-inc/cloud","ref":"v8.5.1131"}`),
	})
